"use client";

import { memo, useId, useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  defaultPeopleGridLabels,
  type PeopleGridColumns,
  type PeopleGridLabels,
  type PeopleGridProps,
} from "./types";
import { PersonCard } from "./parts/person-card";

const COLUMNS_MAP: Record<PeopleGridColumns, string> = {
  2: "grid-cols-1 sm:grid-cols-2",
  3: "grid-cols-1 sm:grid-cols-2 md:grid-cols-3",
  4: "grid-cols-1 sm:grid-cols-2 md:grid-cols-4",
  5: "grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5",
};

const CARD_HEADING_BELOW = { h2: "h3", h3: "h4", h4: "h5" } as const;

function PeopleGridInner({
  items,
  heading,
  headingAs = "h2",
  cardHeadingAs,
  locale,
  columns = 3,
  avatarSize = "lg",
  alignment = "center",
  linkComponent = "a",
  renderItem,
  renderActions,
  renderBadge,
  labels: labelsProp,
  emptyState,
  className,
  headingClassName,
  gridClassName,
  itemClassName,
}: PeopleGridProps) {
  const headingId = useId();
  const HeadingTag = headingAs;

  // `?? "h3"`: an untyped `headingAs` outside h2–h4 (CMS data) still renders, as it did in 0.2.0.
  const cardHeading = cardHeadingAs ?? CARD_HEADING_BELOW[headingAs] ?? "h3";

  // An `undefined` key keeps its default (spread would let it erase the default).
  const emptyTextProp = labelsProp?.emptyText;
  const labels = useMemo<Required<PeopleGridLabels>>(
    () => ({ emptyText: emptyTextProp ?? defaultPeopleGridLabels.emptyText }),
    [emptyTextProp],
  );

  const isEmpty = items.length === 0;

  return (
    <section
      aria-labelledby={heading ? headingId : undefined}
      className={cn("space-y-6", className)}
    >
      {heading && (
        <HeadingTag
          id={headingId}
          className={cn(
            "text-2xl font-bold text-foreground",
            headingClassName,
          )}
        >
          {heading}
        </HeadingTag>
      )}

      {isEmpty ? (
        emptyState ?? (
          <p
            role="status"
            className="text-sm text-muted-foreground"
          >
            {labels.emptyText}
          </p>
        )
      ) : (
        <ul
          role="list"
          className={cn("grid gap-6", COLUMNS_MAP[columns], gridClassName)}
        >
          {items.map((item) =>
            renderItem ? (
              <li key={item.id}>{renderItem(item)}</li>
            ) : (
              <PersonCard
                key={item.id}
                item={item}
                avatarSize={avatarSize}
                alignment={alignment}
                linkComponent={linkComponent}
                itemClassName={itemClassName}
                headingAs={cardHeading}
                locale={locale}
                renderActions={renderActions}
                renderBadge={renderBadge}
              />
            ),
          )}
        </ul>
      )}
    </section>
  );
}

const PeopleGrid = memo(PeopleGridInner);
PeopleGrid.displayName = "PeopleGrid";

export { PeopleGrid };
export default PeopleGrid;

export { PeopleGrid, default } from "./people-grid";

export type {
  PeopleGridItem,
  PeopleGridLabels,
  PeopleGridProps,
  PeopleGridColumns,
  PeopleGridAvatarSize,
  PeopleGridAlignment,
} from "./types";

export { defaultPeopleGridLabels, DEFAULT_PEOPLE_GRID_LABELS } from "./types";

export { getInitials } from "./lib/get-initials";
export type { GetInitialsOptions } from "./lib/get-initials";

// @ilinxa/people-grid 0.3.0

import type { ElementType, ReactNode } from "react";

export type PeopleGridColumns = 2 | 3 | 4 | 5;
export type PeopleGridAvatarSize = "sm" | "md" | "lg";
export type PeopleGridAlignment = "center" | "start";

export interface PeopleGridItem {
  /** Stable identifier. Used for React keys + accessible-name composition. */
  id: string;
  /** Person's display name. Required — drives the initials fallback. */
  name: string;
  /** Role / title (muted, smaller, below name). Optional. */
  title?: string;
  /** Avatar image URL. Optional — falls back to initials circle. */
  image?: string;
  /** Image alt text. Optional — default `""` (decorative: the name is the heading right beside the avatar). */
  imageAlt?: string;
  /** Intrinsic width of `image` in px — passed to `<img width>` (reserves space, avoids layout shift). */
  imageWidth?: number;
  /** Intrinsic height of `image` in px — passed to `<img height>`. */
  imageHeight?: number;
  /** `srcset` for `image` — passed to `<img srcset>`. */
  imageSrcSet?: string;
  /** `sizes` for `imageSrcSet` — passed to `<img sizes>`. */
  imageSizes?: string;
  /** Optional URL — when supplied + `linkComponent` provided, the entire card becomes clickable. */
  href?: string;
}

export interface PeopleGridLabels {
  /** Default: "No people to display." Used when `items` is empty AND `emptyState` not provided. */
  emptyText?: string;
}

export interface PeopleGridProps {
  /** Items to render in display order. */
  items: PeopleGridItem[];

  /** Optional section heading text. */
  heading?: string;
  /** Heading semantic level. Default: 'h2' (people grids are typically top-level page sections). */
  headingAs?: "h2" | "h3" | "h4";
  /**
   * Heading level of each card's name. Default: one level below `headingAs` (h2 -> h3, h3 -> h4, h4 -> h5).
   * `cardHeadingAs="h4"` reproduces the 0.2.0 output.
   */
  cardHeadingAs?: "h3" | "h4" | "h5" | "h6";
  /** BCP 47 locale for the default card's initials casing (`"tr"`: ilker -> İ). */
  locale?: string;

  /** Number of columns at the largest breakpoint. Default: 3. All grids start at 1 col on mobile. */
  columns?: PeopleGridColumns;
  /** Avatar size. Default: 'lg' (w-24 h-24). 'md' = w-16, 'sm' = w-12. */
  avatarSize?: PeopleGridAvatarSize;
  /** Card alignment within each grid cell. Default: 'center'. */
  alignment?: PeopleGridAlignment;

  /** Element used when `item.href` is supplied. Default: 'a'. */
  linkComponent?: ElementType;

  /** Custom per-item renderer — bypasses the default card layout entirely. */
  renderItem?: (item: PeopleGridItem) => ReactNode;
  /**
   * Per-card action slot on the default card (a "Follow" button …). Rendered in a raised wrapper
   * (`relative z-10`), so the card link never swallows its clicks. Tab order: badge, actions, then the card link.
   */
  renderActions?: (item: PeopleGridItem) => ReactNode;
  /** Per-card badge slot on the default card (verified mark …), rendered beside the name in a raised wrapper. */
  renderBadge?: (item: PeopleGridItem) => ReactNode;

  /** Localized labels. An `undefined` key keeps its default. */
  labels?: PeopleGridLabels;

  /** Empty-state slot. Wins over `labels.emptyText`. */
  emptyState?: ReactNode;

  /** Override classes for the root <section>. */
  className?: string;
  /** Override classes for the heading. */
  headingClassName?: string;
  /** Override classes for the grid container. */
  gridClassName?: string;
  /** Override classes per item (the <li>). */
  itemClassName?: string;
}

/** Default English labels — exported for consumer composition. */
export const defaultPeopleGridLabels: Required<PeopleGridLabels> = {
  emptyText: "No people to display.",
};

/** @deprecated Use `defaultPeopleGridLabels`. */
export const DEFAULT_PEOPLE_GRID_LABELS = defaultPeopleGridLabels;

"use client";

import { memo, useId, type ElementType, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import type {
  PeopleGridAlignment,
  PeopleGridAvatarSize,
  PeopleGridItem,
} from "../types";
import { getInitials } from "../lib/get-initials";

interface PersonCardProps {
  item: PeopleGridItem;
  avatarSize: PeopleGridAvatarSize;
  alignment: PeopleGridAlignment;
  linkComponent: ElementType;
  /** Heading level of the person's name. */
  headingAs: "h3" | "h4" | "h5" | "h6";
  locale?: string;
  renderActions?: (item: PeopleGridItem) => ReactNode;
  renderBadge?: (item: PeopleGridItem) => ReactNode;
  itemClassName?: string;
}

const AVATAR_SIZE_MAP: Record<
  PeopleGridAvatarSize,
  { wrapper: string; initials: string }
> = {
  sm: { wrapper: "w-12 h-12", initials: "text-sm" },
  md: { wrapper: "w-16 h-16", initials: "text-base" },
  lg: { wrapper: "w-24 h-24", initials: "text-2xl" },
};

function PersonCardInner({
  item,
  avatarSize,
  alignment,
  linkComponent: LinkComponent,
  headingAs: Heading,
  locale,
  renderActions,
  renderBadge,
  itemClassName,
}: PersonCardProps) {
  const nameId = useId();
  const isLinked = item.href != null && item.href.length > 0;
  const sizeClasses = AVATAR_SIZE_MAP[avatarSize];
  const badge = renderBadge?.(item);
  const actions = renderActions?.(item);
  const centered = alignment === "center";

  return (
    <li
      className={cn(
        "relative group",
        centered ? "text-center" : "text-start",
        itemClassName,
      )}
    >
      <div
        className={cn(
          "rounded-full overflow-hidden border-4 border-primary/20 mb-3",
          sizeClasses.wrapper,
          centered ? "mx-auto" : "",
        )}
      >
        {item.image ? (
          <img
            src={item.image}
            alt={item.imageAlt ?? ""}
            width={item.imageWidth}
            height={item.imageHeight}
            srcSet={item.imageSrcSet}
            sizes={item.imageSizes}
            loading="lazy"
            decoding="async"
            className="w-full h-full object-cover"
          />
        ) : (
          <div
            aria-hidden="true"
            className={cn(
              "w-full h-full flex items-center justify-center bg-primary/10 text-primary font-semibold",
              sizeClasses.initials,
            )}
          >
            {getInitials(item.name, locale)}
          </div>
        )}
      </div>

      <div
        className={cn(
          "flex flex-wrap items-center gap-x-1.5",
          centered ? "justify-center" : "justify-start",
        )}
      >
        <Heading
          id={nameId}
          className="font-semibold text-foreground motion-safe:group-hover:text-primary transition-colors"
        >
          {item.name}
        </Heading>
        {badge != null && badge !== false && (
          <span className="relative z-10 inline-flex items-center">{badge}</span>
        )}
      </div>
      {item.title && (
        <p className="text-sm text-muted-foreground">{item.title}</p>
      )}

      {actions != null && actions !== false && (
        <div
          className={cn(
            "relative z-10 mt-3 flex flex-wrap gap-2",
            centered ? "justify-center" : "justify-start",
          )}
        >
          {actions}
        </div>
      )}

      {isLinked && (
        <LinkComponent
          href={item.href}
          aria-labelledby={nameId}
          className="absolute inset-0 z-0 outline-none rounded-lg focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        />
      )}
    </li>
  );
}

export const PersonCard = memo(PersonCardInner);
PersonCard.displayName = "PersonCard";

const TITLE_PATTERN = /^(Dr|Prof|Mr|Mrs|Ms|Sr|Jr)\.?$/i;

export interface GetInitialsOptions {
  /** BCP 47 tag used for upper-casing (`"tr"`: ilker -> İ). Default: locale-independent upper-casing. */
  locale?: string;
  /**
   * Honorifics to skip. A list (compared case-insensitively, trailing `.` ignored) or a RegExp tested against each
   * word. Replaces the default English list (Dr, Prof, Mr, Mrs, Ms, Sr, Jr).
   */
  honorifics?: readonly string[] | RegExp;
  /** Returned for an empty name. Default `"?"`. */
  fallback?: string;
}

type Segmenter = { segment(input: string): Iterable<{ segment: string }> };

let cachedSegmenter: Segmenter | null | undefined;

function getSegmenter(): Segmenter | null {
  if (cachedSegmenter !== undefined) return cachedSegmenter;
  const Ctor = (Intl as unknown as { Segmenter?: new (l?: string, o?: { granularity: string }) => Segmenter })
    .Segmenter;
  try {
    cachedSegmenter = Ctor ? new Ctor(undefined, { granularity: "grapheme" }) : null;
  } catch {
    cachedSegmenter = null;
  }
  return cachedSegmenter;
}

/** First user-perceived character (grapheme) of `text`; falls back to the first code point. */
function firstGrapheme(text: string): string {
  if (!text) return "";
  const seg = getSegmenter();
  if (seg) {
    for (const part of seg.segment(text)) return part.segment;
  }
  return Array.from(text)[0] ?? "";
}

function upper(text: string, locale?: string): string {
  if (!locale) return text.toUpperCase();
  try {
    return text.toLocaleUpperCase(locale);
  } catch {
    return text.toUpperCase();
  }
}

function isHonorific(word: string, honorifics: GetInitialsOptions["honorifics"], locale?: string): boolean {
  if (!honorifics) return TITLE_PATTERN.test(word);
  if (honorifics instanceof RegExp) {
    honorifics.lastIndex = 0;
    return honorifics.test(word);
  }
  const key = (s: string) => {
    const bare = s.replace(/\.$/, "");
    try {
      return locale ? bare.toLocaleLowerCase(locale) : bare.toLowerCase();
    } catch {
      return bare.toLowerCase();
    }
  };
  const target = key(word);
  return honorifics.some((h) => key(h) === target);
}

/**
 * Pure function. Returns 1-2 uppercase initials from a name (first grapheme of the first and last word).
 *
 * Skips honorifics (default: Dr., Prof., Mr., Mrs., Ms., Sr., Jr.). The second argument is a locale string
 * (shorthand) or an options object.
 *
 * @example
 * getInitials("Dr. Ahmet Yılmaz")        // -> "AY"
 * getInitials("ilker yılmaz", "tr")      // -> "İY"
 * getInitials("Madonna")                 // -> "M"
 * getInitials("")                        // -> "?"
 */
export function getInitials(name: string, options?: string | GetInitialsOptions): string {
  const opts: GetInitialsOptions = typeof options === "string" ? { locale: options } : (options ?? {});
  const fallback = opts.fallback ?? "?";
  const trimmed = name.trim();
  if (!trimmed) return fallback;

  const parts = trimmed.split(/\s+/).filter((p) => !isHonorific(p, opts.honorifics, opts.locale));

  // Upper-case each initial on its own and keep one grapheme: "ß" upper-cases to "SS".
  const initial = (word: string) => firstGrapheme(upper(firstGrapheme(word), opts.locale));

  if (parts.length === 0) {
    return initial(trimmed) || fallback;
  }
  if (parts.length === 1) {
    return initial(parts[0]);
  }
  return initial(parts[0]) + initial(parts[parts.length - 1]);
}
